import numpy as np
import pandas as pd

def rolling_vol(r, w, periods_per_year=252, zero_mean=False):
    s = pd.Series(r, dtype=float)
    if zero_mean:
        daily = np.sqrt((s ** 2).rolling(w).mean())
    else:
        daily = s.rolling(w).std()
    return (daily * np.sqrt(periods_per_year)).to_numpy()

